Here is the root cause:
The bug was caused by holding the line discipline lock during the `tty_reopen()` process, which could interrupt ongoing I/O operations on the tty. This was particularly problematic when a user was in the middle of a login process with a long password, as the lock would block the I/O, leading to a poor user experience. The need to reinitialize the line discipline when it was already present added unnecessary complexity and potential for disruption.

Here is the patch:
  */
 static int tty_reopen(struct tty_struct *tty)
 {
 	struct tty_driver *driver = tty->driver;
-	int retval;
+	struct tty_ldisc *ld;
+	int retval = 0;

 	if (driver->type == TTY_DRIVER_TYPE_PTY &&
 	    driver->subtype == PTY_TYPE_MASTER)
 		return -EIO;

 	if (!tty->count)
 		return -EAGAIN;

 	if (test_bit(TTY_EXCLUSIVE, &tty->flags) && !capable(CAP_SYS_ADMIN))
 		return -EBUSY;

-	retval = tty_ldisc_lock(tty, 5 * HZ);
-	if (retval)
-		return retval;
+	ld = tty_ldisc_ref_wait(tty);
+	if (ld) {
+		tty_ldisc_deref(ld);
+	} else {
+		retval = tty_ldisc_lock(tty, 5 * HZ);
+		if (retval)
+			return retval;

-	if (!tty->ldisc)
-		retval = tty_ldisc_reinit(tty, tty->termios.c_line);
-	tty_ldisc_unlock(tty);
+		if (!tty->ldisc)
+			retval = tty_ldisc_reinit(tty, tty->termios.c_line);
+		tty_ldisc_unlock(tty);
+	}

 	if (retval == 0)
 		tty->count++;

 	return retval;
 }



